// ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the system time.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Zero value is not usable; use New.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // available tokens
	last     time.Time     // last refill time
	nowFn    func() time.Time
}

// New creates a Limiter refilling at rate tokens per second with
// capacity burst. The bucket starts full.
func New(rate float64, burst int, clk Clock) (*Limiter, error) {
	if rate <= 0 || math.IsInf(rate, 0) || math.IsNaN(rate) {
		return nil, errors.New("ratelimit: rate must be positive and finite")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be positive")
	}
	if clk == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	now := clk.Now()
	return &Limiter{
		rate:  rate,
		burst: float64(burst),
		tokens: float64(burst),
		last:  now,
		nowFn: clk.Now,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = math.Min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(l.nowFn(), 1) }

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. It does not consume tokens.
func (l *Limiter) RetryAfter(now time.Time, n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if need > l.burst {
		return -1
	}
	if l.tokens >= need {
		return 0
	}
	return time.Duration((need - l.tokens) / l.rate * float64(time.Second))
}
