		burst   int
		clk     Clock
		wantErr bool
	}{
		{"ok", 1, 1, clk, false},
		{"zero rate", 0, 1, clk, true},
		{"negative rate", -1, 1, clk, true},
		{"NaN rate", nan(), 1, clk, true},
		{"Inf rate", inf(), 1, clk, true},
		{"zero burst", 1, 0, clk, true},
		{"negative burst", 1, -1, clk, true},
		{"nil clock", 1, 1, nil, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, tc.clk)
