		t.Fatalf("RetryAfter = %v, want 250ms", d)
	}
	clk.Advance(250 * time.Millisecond)
	if d := l.RetryAfter(clk.t, 1); d != 0 {
		t.Fatalf("RetryAfter = %v, want 0", d)
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l := mustNew(t, 1000, 100, clk)
	const goroutines = 50
	results := make(chan bool, goroutines)
	for i := 0; i < goroutines; i++ {
		go func() { results <- l.Allow() }()
	}
	allowed := 0
	for i := 0; i < goroutines; i++ {
		if <-results {
			allowed++
		}
	}
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
