// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by NewLimiter and is safe for concurrent use.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	capacity  int
	rate      float64 // tokens per second
	tokens    float64
	lastRefill time.Time
}

// ErrInvalidConfig is returned by NewLimiter for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// NewLimiter creates a Limiter that starts full with capacity tokens,
// refilling at rate tokens per second.
func NewLimiter(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock
	}
	return &Limiter{
		clock:      clock,
		capacity:   capacity,
		rate:       rate,
		tokens:     float64(capacity),
		lastRefill: clock.Now(),
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It never blocks.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.capacity) {
			l.tokens = float64(l.capacity)
		}
		l.lastRefill = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.lastRefill).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > float64(l.capacity) {
		t = float64(l.capacity)
	}
	return t
}
